int vx_profiling_register(SynurangInstance* instance,
    const VxProfilingServiceHandlers* handlers, void* service) {
    int status;
    if (instance == NULL || handlers == NULL) return SYNURANG_INVALID_ARGUMENT;

    {
        vx_profiling_start_trace_registration* registration =
            (vx_profiling_start_trace_registration*)malloc(sizeof(*registration));
        if (registration == NULL) return SYNURANG_OUT_OF_MEMORY;
        registration->handler = handlers->start_trace;
        registration->service = service;
        status = synurang_instance_register(instance, "/volvoxai.v1.VxProfilingService/StartTrace",
            0u,
            0u,
            vx_profiling_start_trace_create, registration, free);
        if (status != SYNURANG_OK) { free(registration); return status; }
    }

    {
        vx_profiling_stop_trace_registration* registration =
            (vx_profiling_stop_trace_registration*)malloc(sizeof(*registration));
        if (registration == NULL) return SYNURANG_OUT_OF_MEMORY;
        registration->handler = handlers->stop_trace;
        registration->service = service;
        status = synurang_instance_register(instance, "/volvoxai.v1.VxProfilingService/StopTrace",
            0u,
            0u,
            vx_profiling_stop_trace_create, registration, free);
        if (status != SYNURANG_OK) { free(registration); return status; }
    }

    {
        vx_profiling_get_trace_registration* registration =
            (vx_profiling_get_trace_registration*)malloc(sizeof(*registration));
        if (registration == NULL) return SYNURANG_OUT_OF_MEMORY;
        registration->handler = handlers->get_trace;
        registration->service = service;
        status = synurang_instance_register(instance, "/volvoxai.v1.VxProfilingService/GetTrace",
            0u,
            0u,
            vx_profiling_get_trace_create, registration, free);
        if (status != SYNURANG_OK) { free(registration); return status; }
    }

    {
        vx_profiling_read_trace_registration* registration =
            (vx_profiling_read_trace_registration*)malloc(sizeof(*registration));
        if (registration == NULL) return SYNURANG_OUT_OF_MEMORY;
        registration->handler = handlers->read_trace;
        registration->service = service;
        status = synurang_instance_register(instance, "/volvoxai.v1.VxProfilingService/ReadTrace",
            0u,
            0u,
            vx_profiling_read_trace_create, registration, free);
        if (status != SYNURANG_OK) { free(registration); return status; }
    }

    {
        vx_profiling_export_chrome_trace_registration* registration =
            (vx_profiling_export_chrome_trace_registration*)malloc(sizeof(*registration));
        if (registration == NULL) return SYNURANG_OUT_OF_MEMORY;
        registration->handler = handlers->export_chrome_trace;
        registration->service = service;
        status = synurang_instance_register(instance, "/volvoxai.v1.VxProfilingService/ExportChromeTrace",
            0u,
            0u,
            vx_profiling_export_chrome_trace_create, registration, free);
        if (status != SYNURANG_OK) { free(registration); return status; }
    }

    {
        vx_profiling_release_trace_registration* registration =
            (vx_profiling_release_trace_registration*)malloc(sizeof(*registration));
        if (registration == NULL) return SYNURANG_OUT_OF_MEMORY;
        registration->handler = handlers->release_trace;
        registration->service = service;
        status = synurang_instance_register(instance, "/volvoxai.v1.VxProfilingService/ReleaseTrace",
            0u,
            0u,
            vx_profiling_release_trace_create, registration, free);
        if (status != SYNURANG_OK) { free(registration); return status; }
    }

    {
        vx_profiling_get_memory_snapshot_registration* registration =
            (vx_profiling_get_memory_snapshot_registration*)malloc(sizeof(*registration));
        if (registration == NULL) return SYNURANG_OUT_OF_MEMORY;
        registration->handler = handlers->get_memory_snapshot;
        registration->service = service;
        status = synurang_instance_register(instance, "/volvoxai.v1.VxProfilingService/GetMemorySnapshot",
            0u,
            0u,
            vx_profiling_get_memory_snapshot_create, registration, free);
        if (status != SYNURANG_OK) { free(registration); return status; }
    }

    return SYNURANG_OK;
}


