int vx_text_register(SynurangInstance* instance,
    const VxTextServiceHandlers* handlers, void* service) {
    int status;
    if (instance == NULL || handlers == NULL) return SYNURANG_INVALID_ARGUMENT;

    {
        vx_text_create_tokenizer_registration* registration =
            (vx_text_create_tokenizer_registration*)malloc(sizeof(*registration));
        if (registration == NULL) return SYNURANG_OUT_OF_MEMORY;
        registration->handler = handlers->create_tokenizer;
        registration->service = service;
        status = synurang_instance_register(instance, "/volvoxai.v1.VxTextService/CreateTokenizer",
            0u,
            0u,
            vx_text_create_tokenizer_create, registration, free);
        if (status != SYNURANG_OK) { free(registration); return status; }
    }

    {
        vx_text_encode_text_registration* registration =
            (vx_text_encode_text_registration*)malloc(sizeof(*registration));
        if (registration == NULL) return SYNURANG_OUT_OF_MEMORY;
        registration->handler = handlers->encode_text;
        registration->service = service;
        status = synurang_instance_register(instance, "/volvoxai.v1.VxTextService/EncodeText",
            0u,
            0u,
            vx_text_encode_text_create, registration, free);
        if (status != SYNURANG_OK) { free(registration); return status; }
    }

    {
        vx_text_decode_tokens_registration* registration =
            (vx_text_decode_tokens_registration*)malloc(sizeof(*registration));
        if (registration == NULL) return SYNURANG_OUT_OF_MEMORY;
        registration->handler = handlers->decode_tokens;
        registration->service = service;
        status = synurang_instance_register(instance, "/volvoxai.v1.VxTextService/DecodeTokens",
            0u,
            0u,
            vx_text_decode_tokens_create, registration, free);
        if (status != SYNURANG_OK) { free(registration); return status; }
    }

    {
        vx_text_release_tokenizer_registration* registration =
            (vx_text_release_tokenizer_registration*)malloc(sizeof(*registration));
        if (registration == NULL) return SYNURANG_OUT_OF_MEMORY;
        registration->handler = handlers->release_tokenizer;
        registration->service = service;
        status = synurang_instance_register(instance, "/volvoxai.v1.VxTextService/ReleaseTokenizer",
            0u,
            0u,
            vx_text_release_tokenizer_create, registration, free);
        if (status != SYNURANG_OK) { free(registration); return status; }
    }

    return SYNURANG_OK;
}


