typedef struct vx_scheduler_submit_registration {
    VxSchedulerServiceSubmitHandler handler;
    void* service;
} vx_scheduler_submit_registration;
typedef struct vx_scheduler_submit_state {
    vx_scheduler_submit_registration registration;
    SynurangCallOptions options;
    void* call;
} vx_scheduler_submit_state;
SynurangStatus vx_scheduler_submit_respond(SynurangStream* stream, const VolvoxaiV1RequestHandle* message) {
    uint8_t* data = NULL;
    size_t size = 0u;
    SynurangStatus status;
    const SynurangLiteAllocator* allocator;
    if (message == NULL || stream == NULL) return SYNURANG_INVALID_ARGUMENT;
    if (volvoxai_v1_request_handle_encode(message, &data, &size) != SYNURANG_LITE_OK)
        return SYNURANG_INTERNAL;
    status = synurang_stream_write(stream, data, size);
    allocator = message->_allocator;
    if (allocator == NULL) allocator = synurang_lite_default_allocator();
    if (data != NULL) allocator->deallocate(allocator->context, data);
    return status;
}
static void vx_scheduler_submit_open(SynurangStream* stream, void* user_data) {
    vx_scheduler_submit_state* state = (vx_scheduler_submit_state*)user_data;
    if (state->registration.handler.open == NULL &&
        state->registration.handler.message == NULL &&
        state->registration.handler.half_close == NULL &&
        state->registration.handler.writable == NULL &&
        state->registration.handler.cancel == NULL &&
        state->registration.handler.destroy == NULL) {
        (void)synurang_stream_fail_error(stream, 0, 12, "Unimplemented method");
        return;
    }
    if (state->registration.handler.open != NULL)
        state->call = state->registration.handler.open(
            stream, &state->options, state->registration.service);
}
static void vx_scheduler_submit_message(SynurangStream* stream, const uint8_t* data,
                         size_t size, void* user_data) {
    vx_scheduler_submit_state* state = (vx_scheduler_submit_state*)user_data;
    VolvoxaiV1SubmitRequest request;
    volvoxai_v1_submit_request_init(&request);
    if (volvoxai_v1_submit_request_decode(&request, data, size) != SYNURANG_LITE_OK)
        (void)synurang_stream_fail_error(stream, 0, 3, "Malformed request");
    else if (state->registration.handler.message != NULL)
        state->registration.handler.message(stream, &request, state->call);
    else
        (void)synurang_stream_fail_error(stream, 0, 12, "Unimplemented method");
    volvoxai_v1_submit_request_free(&request);
}
static void vx_scheduler_submit_half_close(SynurangStream* stream, void* user_data) {
    vx_scheduler_submit_state* state = (vx_scheduler_submit_state*)user_data;
    if (state->registration.handler.half_close != NULL)
        state->registration.handler.half_close(stream, state->call);
}
static void vx_scheduler_submit_writable(SynurangStream* stream, void* user_data) {
    vx_scheduler_submit_state* state = (vx_scheduler_submit_state*)user_data;
    if (state->registration.handler.writable != NULL)
        state->registration.handler.writable(stream, state->call);
}
static void vx_scheduler_submit_cancel(SynurangStream* stream, void* user_data) {
    vx_scheduler_submit_state* state = (vx_scheduler_submit_state*)user_data;
    if (state->registration.handler.cancel != NULL)
        state->registration.handler.cancel(stream, state->call);
}
static void vx_scheduler_submit_destroy(void* user_data) {
    vx_scheduler_submit_state* state = (vx_scheduler_submit_state*)user_data;
    if (state->registration.handler.destroy != NULL)
        state->registration.handler.destroy(state->call);
    free(state);
}
static uint64_t vx_scheduler_submit_create(SynurangRuntime* runtime,
    const SynurangCallOptions* options, void* user_data) {
    vx_scheduler_submit_state* state = (vx_scheduler_submit_state*)calloc(1u, sizeof(*state));
    const SynurangStreamCallbacks callbacks = {
        sizeof(SynurangStreamCallbacks), vx_scheduler_submit_open, vx_scheduler_submit_message,
        vx_scheduler_submit_half_close, vx_scheduler_submit_writable, vx_scheduler_submit_cancel, vx_scheduler_submit_destroy
    };
    uint64_t handle;
    if (state == NULL) return 0u;
    state->registration = *(vx_scheduler_submit_registration*)user_data;
    state->options = *options;
    state->call = state->registration.handler.open != NULL
        ? NULL : state->registration.service;
    handle = synurang_stream_open(runtime, &callbacks, state);
    if (handle == 0u) free(state);
    return handle;
}

